def transform(g):
    g=[row[:] for row in g]
    blue=red=None
    for i,r in enumerate(g):
        for j,v in enumerate(r):
            if v==1: blue=(i,j)
            if v==2: red=(i,j)
    (br,bc),(rr,rc)=blue,red
    sr=1 if rr>br else -1; sc=1 if rc>bc else -1
    i,j=br,bc
    while True:
        ni,nj=i+sr,j+sc
        if not(0<=ni<len(g) and 0<=nj<len(g[0])): break
        i,j=ni,nj
        if g[i][j]==0: g[i][j]=3
        if abs(i-rr)<=1 or abs(j-rc)<=1: break
    if abs(j-rc)>1:  # columns still differ -> move horizontally
        step=1 if rc>j else -1
        while abs(j+step-rc)>1:
            j+=step
            if g[i][j]==0: g[i][j]=3
    elif abs(i-rr)>1:
        step=1 if rr>i else -1
        while abs(i+step-rr)>1:
            i+=step
            if g[i][j]==0: g[i][j]=3
    return g
